"""Sanitized study aggregates. No raw source, user identity, API secrets or paid calls."""
import argparse,json,re,statistics
from pathlib import Path
from summarize_cost import estimate

def main(args):
    root=args.study;ref=json.loads((root/'reference.json').read_text());wire=[json.loads(s) for s in (root/'model-phase/wire.jsonl').read_text().splitlines()];rates=json.loads((root/'rates.json').read_text());requests={r['index']:r for r in wire if r['event']=='request'};by_model={};by_condition={}
    for row in wire:
        model=row['model'] if row['event']=='request' else requests[row['index']]['model'];condition=re.sub(r'-\d+$','',re.sub(r'-batch\d+$','',row['label']));by_model.setdefault(model,[]).append(row);by_condition.setdefault(condition,[]).append(row)
    model_cost={model:estimate(rows,rates['ratesPerMillion'][model]) for model,rows in by_model.items()};condition_cost={}
    for name,rows in by_condition.items():
        models={r['model'] for r in rows if r['event']=='request'}
        if len(models)!=1:raise ValueError('mixed_model_cost_condition')
        model=next(iter(models));value=estimate(rows,rates['ratesPerMillion'][model]);times=[r['wallSeconds'] for r in rows if r['event']=='response'];value['model']=model;value['medianHttpSeconds']=statistics.median(times) if times else None;value['sumHttpSeconds']=sum(times);condition_cost[name]=value
    totals={'requests':sum(v['requests'] for v in model_cost.values()),'responses':sum(v['responses'] for v in model_cost.values()),'unknownUsageResponses':sum(v['unknownUsageResponses'] for v in model_cost.values()),'estimatedPublishedUsd':sum(v['estimatedPublishedUsd'] for v in model_cost.values()),'tokens':{key:sum(v['tokens'][key] for v in model_cost.values()) for key in ['input','ordinaryInput','cacheRead','cacheWrite','output']}}
    disparities=[r['index'] for r in wire if r['event']=='response' and r.get('usage') and r['usage']['input_tokens']+r['usage']['output_tokens']!=r['usage'].get('total_tokens')]
    scores=json.loads((root/'scores.json').read_text());lemma=json.loads((root/'lemma-scores.json').read_text());sense_ref=json.loads((root/'sense-reference.json').read_text());sense_scores={}
    for p in root.glob('sense-*-validated.json'):
        raw=json.loads(p.read_text());byid={r['caseId']:r for r in raw['decisions']};certain=[c for c in sense_ref['cases'] if c['expected']!='uncertain'];sense_scores[p.stem.removesuffix('-validated')]={'certainCases':len(certain),'agreesWithOperatorReference':sum(byid[c['caseId']]['verdict']==c['expected'] for c in certain),'falseVetoes':sum(c['expected']=='accept' and byid[c['caseId']]['verdict']=='reject' for c in certain),'wrongAccepts':sum(c['expected']=='reject' and byid[c['caseId']]['verdict']=='accept' for c in certain),'uncertainOnCertain':sum(byid[c['caseId']]['verdict']=='uncertain' for c in certain),'disagreements':[{'caseId':c['caseId'],'expected':c['expected'],'actual':byid[c['caseId']]['verdict']} for c in certain if byid[c['caseId']]['verdict']!=c['expected']]}
    parsers={name:json.loads((root/(name+'.json')).read_text())['metrics'] for name in ['spacy-nl_core_news_sm','spacy-nl_core_news_md','stanza-alpino']}
    a=json.loads((root/'luna-taxonomy-validated.json').read_text())['units'];b=json.loads((root/'luna-taxonomy-repeat-validated.json').read_text())['units'];sa={(u['caseId'],tuple(u['tokenIds'])) for u in a};sb={(u['caseId'],tuple(u['tokenIds'])) for u in b}
    result={'date':'2026-10-18','referenceStatus':ref['referenceStatus'],'referenceSha256':ref['referenceSha256'],'cases':len(ref['cases']),'requiredUnits':sum(len(c['required']) for c in ref['cases']),'optionalUnits':sum(len(c['optional']) for c in ref['cases']),'lemmaReferenceSha256':json.loads((root/'lemma-reference.json').read_text())['referenceSha256'],'senseReferenceSha256':sense_ref['referenceSha256'],'sourceKinds':{'nos':'author captions','easy':'own AudioFilms ASR','lubach':'own AudioFilms ASR'},'resource':'dilumio-01-resource','region':'swedencentral','subscriptionOffer':'Microsoft Azure Sponsorship','deployments':{'gpt-6-luna':{'version':'2026-09-22','sku':'GlobalStandard'},'gpt-6.1-sol':{'version':'2026-09-29','sku':'GlobalStandard'}},'firstModelRequestUtc':min(r['utc'] for r in requests.values()),'lastModelRequestUtc':max(r['utc'] for r in requests.values()),'timezone':'Europe/Amsterdam','observedResponseModels':sorted({r['model'] for r in wire if r['event']=='response' and r.get('model')}),'modelUsage':totals,'byModel':model_cost,'byCondition':condition_cost,'rates':rates,'requestBytesTotal':sum(r['requestBytes'] for r in requests.values()),'peakRequestBytes':max(r['requestBytes'] for r in requests.values()),'usageTotalDiscrepancies':disparities,'httpStatuses':sorted({r['status'] for r in wire if r['event']=='response'}),'extractionScores':{k:{scope:{n:v for n,v in d.items() if n!='caseDetails'} for scope,d in value.items()} for k,value in scores.items()},'lemmaScores':{k:{n:v for n,v in d.items() if n!='details'} for k,d in lemma.items()},'senseScores':sense_scores,'localParserMetrics':parsers,'repeatability':{'firstUnitCores':len(sa),'secondUnitCores':len(sb),'commonCores':len(sa&sb),'symmetricDifference':len(sa^sb)},'verificationRecovery':{'originalRequested':16,'originalReturned':3,'missingReviewedSeparately':59,'repairedBatchMax':8,'reviewedUnionCores':62,'transportRetries':0},'productionWrites':0,'newDictionaryArticles':0,'priorModelRequests':154,'cumulativeModelRequests':154+totals['requests'],'priorPublishedEstimateUsd':.126051325,'cumulativePublishedEstimateUsd':.126051325+totals['estimatedPublishedUsd'],'limits':['small operator challenge set, sources already inspected; not held-out independent gold','rule baselines are two dependency heuristics, not specialized trained MWE detectors','exact lexical-core policy is product-specific; partial IoU is not official PARSEME partial score','optional labels neutral; unlabelled plausible collocations need human adjudication','canonical exact-string scores are naming consistency, not semantic correctness','sense set intentionally selects known disagreements; not full-video accuracy','same sources reused, no audio quality evaluation or production integration','published token prices, no invoice reconciliation or local CPU monetization']}
    args.output.write_text(json.dumps(result,ensure_ascii=False,indent=2)+'\n');print(json.dumps({'cost':totals,'senseScores':sense_scores,'requests':totals['requests']},indent=2))
if __name__=='__main__':
    p=argparse.ArgumentParser();p.add_argument('study',type=Path);p.add_argument('output',type=Path);main(p.parse_args())
